L16: async function run(options, ...command) {
L17:   const proc = Bun.spawn(command, {
L18:     ...options,
L19:     stdout: "pipe",
L20:     stderr: "ignore"
L21:   });
L22:   const stdout = await proc.stdout.text();
L23:   return {
L24:     code: await proc.exited,
L25:     stdout: stdout.trim()
L26:   };
L27: }
L28: async function fetchPr(signal, target) {
L29:   try {
L30:     const result = await run({
L31:       cwd: target.directory,
L32:       signal
L33:     }, "gh", "pr", "view", ...(target.url ? [target.url] : []), "--json", PR_FIELDS);
L34:     if (result.code !== 0) return undefined;
L35:     const parsed = JSON.parse(result.stdout);
L36:     if (typeof parsed !== "object" || parsed === null) return undefined;
L37:     const pr = parsed;
L38:     return typeof pr.number === "number" && typeof pr.url === "string" ? pr : undefined;
L39:   } catch {
L40:     return undefined;
L41:   }
L42: }
